code.perFrame:
now=gettime(0) ; sec=now-last ; last=now ;
asp=h/w ; reg07=asp ; reg09=h/280 ;

bnd=0 ; // volume
loop(1000,exec2(assign(bnd,bnd+0.001),assign(vol,vol+(getspec(bnd*0.4,0,0)+sqrt(sqr(getosc(bnd,0,0))))*0.5))) ;
vol=vol*0.95 ; volume=vol*0.001 ;

reg00=sec ; reg01=volume ;
volsec=(0.5+volume*0.8)*sec ;

// rotation
c=if(above(c,2.5),0,c+volsec) ; eql=equal(c,0) ;
lxts=if(eql,xts,lxts) ;
lyts=if(eql,yts,lyts) ;
lzts=if(eql,zts,lzts) ;
xts=if(eql,(rand(201)-100)*0.0085,xts) ;
yts=if(eql,(rand(201)-85)*0.007,yts) ;
zts=if(eql,(rand(261)-150)*0.01,zts) ;
nxts=if(eql,xts-lxts,nxts) ;
nyts=if(eql,yts-lyts,nyts) ;
nzts=if(eql,zts-lzts,nzts) ;
xt=xt-(xt+xts)*volsec ;
yt=yt-(yt+yts)*volsec ;
zt=zt-(zt+zts)*volsec ;
tilt=if(eql,$pi,tilt*(1-volsec*2)) ; rota=sin(tilt)*0.5 ;
xr=-$pi*0.5+rota*nzts ; yr=-rota*nxts*1.5 ;

pump=sin(tilt) ; reg08=pump*nyts*0.5 ;

reg04=xt ; reg05=yt ; reg06=zt ;

reg10=sin(xr) ; reg11=cos(xr) ; reg12=sin(yr) ; reg13=cos(yr) ;

